csui.define('d2/overrides/csui/utils/context/perspective/plugins/node/node.perspective.context.plugin',[
  'nuc/lib/underscore',
  'csui/utils/contexts/perspective/plugins/node/node.perspective.context.plugin',
  'd2/utils/constants',
  'd2/utils/widgets.utils',
], function(_, NodePerspectiveContextPlugin, constants, widgetUtils){
  'use strict';

  var orig_changePerspective = NodePerspectiveContextPlugin.prototype._changePerspective,
      oldNodeFetchFailure = NodePerspectiveContextPlugin.prototype.onNodeFetchFailure;


  NodePerspectiveContextPlugin.prototype._changePerspective = function () {
    var children = this.context.hasCollection('children') &&
      this.context.getCollection('children') ||
      this.context.hasCollection('children2') &&
      this.context.getCollection('children2');

    children && _.isFunction(children.resetLimit) && children.resetLimit();
    orig_changePerspective.apply(this, arguments);
  },

  /**
   DTWO-102827: This method has been overridden here to remove the local storage in case of no id present.
  **/
  NodePerspectiveContextPlugin.prototype.onNodeFetchFailure = function () {
    oldNodeFetchFailure.apply(this, arguments);
    widgetUtils.clearFolderPathInfo(this.nextNode?.widgetName);
  }
});