csui.define('d2/integration/adapter/embed.base.adapter',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/backbone'
], function ($, _, Backbone) {
  'use strict';

  var EmbedBaseAdapter = function(options) {
    options = options || {};
    this.context = options.context;
    this.connector = options.connector;
    this.params = options.params;
  };

  _.extend(EmbedBaseAdapter.prototype, Backbone.Events, {
    /**
     * Implementation class can use this method to perform any checks before actual action is executed. It must return
     * a promise..
     */
    preProcess: function () {
      return $.Deferred().resolve().promise();
    },

    /**
     * Implementation class can use this method to perform any checks after actual action is executed.
     */
    postProcess: function () {
      return;
    }
  });

  EmbedBaseAdapter.extend = Backbone.View.extend;
  return EmbedBaseAdapter;
});