csui.define('d2/controls/form/fields/alpaca/alpd2labelfield',[
  'nuc/lib/underscore', 'nuc/lib/jquery', 'nuc/lib/backbone',
  'nuc/lib/marionette', 'csui/lib/alpaca/js/alpaca.lite',
  'csui/controls/form/fields/alpaca/alpcsuitextfield',
  'd2/controls/form/fields/d2labelfield.view'
], function (_, $, Backbone, Marionette, Alpaca,
             AlpacaCsuiTextField, D2LabelFieldView) {
  'use strict';

  Alpaca.Fields.D2LabelField = Alpaca.Fields.CsuiTextField.extend({
    constructor: function D2LabelField(container, data, options, schema, view,
                                            connector,
                                            onError) {
      schema.disabled = true;
      schema.readonly = true;
      this.base(container, data, options, schema, view, connector, onError);
    },

    getFieldType: function () {
      return 'd2label';
    },

    showField: function () {

      var id = this.id;

      // add an id to the <label> element like alpaca23Label
      var id4Label,
        labelElement = $(this.field[0]).find('label');

      if (labelElement && labelElement.length===1) {
        id4Label = labelElement.attr('for') + "Label";
        labelElement.attr('id', id4Label);
      }

      // our field
      this.fieldView = new D2LabelFieldView({
        model: new Backbone.Model({
          data: this.data,
          options: this.options,
          schema: this.schema,
          inputType: 'text',
          id: id // <input type=text
        }),
        id: _.uniqueId(id), // wrapper <div>
        alpacaField: this,
        labelId: id4Label,
        value: this.data,
        readonly: true,
        dataId: this.name,
        path: this.path,
        alpaca: {
          data: this.data,
          options: this.options,
          schema: this.schema
        }
      });

      // replace alpaca control with empty div having same classes as control
      var $field = $('<div>').addClass('alpaca-control');
      this.getControlEl().replaceWith($field);

      // show our field in div
      this.region = new Marionette.Region({el: $field});
      this.region.show(this.fieldView);

      return;
    }
  });

  Alpaca.registerFieldClass('d2label', Alpaca.Fields.D2LabelField, 'bootstrap-csui');

  return Alpaca.Fields.D2LabelField;
});