csui.define('d2/overrides/csui/models/command',[
  'nuc/lib/underscore',
  'csui/models/command'
], function (_, CommandModel) {
  'use strict';

  /**
   * Override for "enabled" check. The change boils down to having extra check to ensure that "menu id" also matches
   * in addition to command_key/signature for the action. This allows us to have multiple items with same command_key.
   */
  CommandModel.prototype.enabled = function (status/*, options*/) {
    var scope = this.get('scope'),
      nodes = this._getNodesByScope(status, scope),
      commandKeys = this.get('command_key'),
      data = status.data || {};

    // If no command keys are provided by the command then we don't do any check (always enabled)
    if (!commandKeys || commandKeys.length === 0) {
      return true;
    }

    if (_.isString(commandKeys)) {
      commandKeys = [commandKeys];
    }

    // If no nodes are provided then we don't allow the action
    if (!nodes || nodes.length === 0) {
      return false;
    }

    var enabled = true;
    _.each(nodes, function (node) {
      enabled = enabled && _.some(commandKeys, function (commandKey) {
        var actions = node.actions && node.actions.models;
        if (actions) {
          return _.some(actions, function (action) {
            if (action.get('signature') === commandKey) {
              /* If status provides data, then we compare the menuId from the same with action's menuId.
               * If not, we don't need to compare as it is possible that command is being executed from place other
               * than action toolbar, etc. (e.g. button in Overview perspective) */
              if (data.menuId) {
                var actionMenuId = (action.get('commandData') || {}).menuId || '';
                return (actionMenuId === data.menuId);
              } else {
                return true;
              }
            } else {
              return false;
            }
          });
        }
        return false;
      });
      // If action is not allowed for a node, then stop checking for other nodes
      if (!enabled) {
        return false;
      }
    });

    return enabled;
  };

  CommandModel.prototype.isNonPromoted = function (status) {
    var scope = this.get("scope"),
      nodes = this._getNodesByScope(status, scope),
      signatures = this.get("command_key"),
      isNonPromoted = false;

    // if at least one node is selected and at least one selected node
    // has action which is non-promoted
    if (nodes && nodes.length) {
      var checkFn = getNonPromotedCheckFunctionsForSignaturesAndMenuId(signatures, status.data && status.data.menuId);
      if (checkFn) {
        _.find(nodes, function (node) {
          var action = checkFn(node);
          if (action && action.get('csuiNonPromotedAction') === true && action.get('csuiNonPromotedItem') !== false) {
            isNonPromoted = true;
            return true;
          }
        });
      }
    }
    return isNonPromoted;
  }

  function getNonPromotedCheckFunctionsForSignaturesAndMenuId(signatures, menuId) {
    var checkFn;
    if (signatures) {
      if (_.isArray(signatures) && signatures.length) {
        checkFn = function (node) {
          var action;
          _.find(signatures, function (signature) {
            action = node.actions && node.actions.findRecursively(signature, menuId);
            return !!action;
          });
          return action;
        };
      } else if (_.isString(signatures)) {
        checkFn = function (node) {
          return node.actions && node.actions.findRecursively(signatures, menuId);
        };
      }
    }
    return checkFn;
  }

});
