csui.define('d2/controls/form/fields/alpaca/alpd2checkboxfield',[
  'nuc/lib/underscore', 'nuc/lib/jquery', 'nuc/lib/backbone',
  'nuc/lib/marionette', 'csui/lib/alpaca/js/alpaca.lite',
  'd2/controls/form/fields/d2checkboxfield.view',
  'i18n!d2/controls/form/impl/nls/lang'
], function (_, $, Backbone, Marionette, Alpaca,
             CheckboxFieldView, lang) {
  'use strict';

  Alpaca.Fields.CsuiCheckboxField = Alpaca.Fields.CheckBoxField.extend({
    constructor: function CsuiCheckboxField(container, data, options, schema, view,
                                            connector,
                                            onError) {
      this.base(container, data, options, schema, view, connector, onError);
    },

    getFieldType: function () {
      return 'd2checkbox';
    },

    getFieldViewClass: function () {
      return CheckboxFieldView;
    },

    postRender: function (callback) {
      this.base(callback);
      this.showField();
    },
    isValidationParticipant: function () {
      var result = this.base();
      return result && !this.schema.disabled;
    },

    isRequired: function () {
      var result = this.base();
      return result && !this.schema.disabled;
    },

    showField: function () {
      var collectionData = [], enums = [], optionLabels = [];
      if (_.isFunction(this.options.dataSource)) {
        this.options.dataSource(function (dataArray) {
          collectionData = _.map(dataArray, function (data) {
            enums.push(data.value);
            optionLabels.push(data.text);
            return {id: data.value, name: data.text, category: data.category};
          });
        });
        this.schema.enum = enums;
        this.options.optionLabels = optionLabels;
      }

      var collection = new Backbone.Collection(collectionData),
        selection = new Backbone.Model({
          id: this.name,
          data: _.isArray(this.data) ? this.data : []
        }),
        hasValue = !(_.isEmpty(this.data));

      // add an id to the <label> element like alpaca23Label
      var id4Label,
        labelElement = $(this.field[0]).find('label');

      if (labelElement && labelElement.length === 1) {
        id4Label = labelElement.attr('for') + "Label";
        labelElement.attr('id', id4Label);
      }

      // create csui field
      var id = this.id,
        fieldViewClass = this.getFieldViewClass();

      this.fieldView = new fieldViewClass({
        model: new Backbone.Model({
          data: this.data,
          options: this.options,
          schema: this.schema,
          id: id
        }),
        id: _.uniqueId(id), // wrapper <div>
        alpacaField: this,
        labelId: id4Label, // this will remain undefined if the label does not exist
        selected: selection,
        collection: collection,
        mode: this.options.mode,
        path: this.path,
        dataId: this.name,
        alpaca: {
          data: this.data,
          options: this.options,
          schema: this.schema
        },
        hasValue: hasValue,
        originatingView: this.parent && this.parent.options && this.parent.options.originatingView
      });

      // replace alpaca control with empty div having same classes as control
      var $field = $('<div>').addClass('alpaca-control');
      this.getControlEl().replaceWith($field);

      // show our field in div
      this.region = new Marionette.Region({el: $field});
      this.region.show(this.fieldView);
    },

    setValueAndValidate: function (value, validate) {
      this.setValue((value instanceof Backbone.Model) ? value.get('data') : value);
      var bIsValid = true;
      if (validate) {
        bIsValid = this.validate();
        this.refreshValidationState(false);
      }
      return bIsValid;
    },

    _validator: function (callback) {
      var value = this.getValue();

      if (this.schema.required && _.isEmpty(value)) {
        callback({
          "status": false,
          "message": lang.checkboxFieldValidationErrorRequired
        });
      } else {
        callback({
          "status": true
        });
      }
    },

    validate: function () {
      var isValid = this.base();

      // remove invalidValueOfEnum else will show up in the val message.
      this.validation = _.omit(this.validation, "invalidValueOfEnum");

      return isValid;
    },

    setValue: function (value) {
      value === null ? this.base([]) : this.base(value);
    },

    getValue: function () {
      return this.data;
    },

    focus: function () {
      this.fieldView.setFocus();
    },

    destroy: function () {
      this.base();
      if (this.region) {
        this.region.destroy();
      }
    }
  });

  Alpaca.registerFieldClass('d2checkbox', Alpaca.Fields.CsuiCheckboxField, 'bootstrap-csui');

  return Alpaca.Fields.CsuiCheckboxField;
});
