csui.define('d2/controls/form/fields/listfieldview/d2listfieldoptions.view',['nuc/lib/underscore', 'nuc/lib/jquery', 'nuc/lib/backbone', 'nuc/lib/marionette',
    'csui/controls/tile/behaviors/perfect.scrolling.behavior',
    'csui/controls/tile/behaviors/infinite.scrolling.behavior',
    'csui/controls/form/pub.sub',
    'dctmw/utils/utils',
    'd2/utils/combo.datasource.utils',
    'i18n!d2/controls/form/impl/nls/lang',
    'd2/controls/form/fields/models/field.option',
    'd2/controls/form/fields/listfieldview/d2listfieldoptionsitem.view',
    'hbs!d2/controls/form/impl/d2list/d2listfieldoptions.view'
  ],
  function (_, $, Backbone, Marionette, PerfectScrollingBehavior, InfiniteScrollingBehavior, PubSub, utils, ComboDataSourceUtils, Lang, FieldOptionModel, OptionsItemView, OptionsViewTemplate) {
    'use strict';

    return Marionette.CompositeView.extend({
      childView: OptionsItemView,
      childViewContainer: ".d2-listfield-options",
      childViewOptions: function () {
        return {
          parentView: this
        };
      },
      template: OptionsViewTemplate,
      className: "d2-listfield-options-wrapper",
      behaviors: {
        PerfectScrolling: {
          behaviorClass: PerfectScrollingBehavior,
          contentParent: '> .d2-listfield-options',
          suppressScrollX: true
        },
        InfiniteScrolling: {
          behaviorClass: InfiniteScrollingBehavior,
          // selector for scrollable area
          contentParent: 'ul.d2-listfield-options',
          // fetchMoreItemsThreshold: 90,
          content: 'ul.d2-listfield-options>li:visible'
        }
      },
      ui: {
        options: ".d2-listfield-options",
        addNewOption: ".d2-add-new-option",
        noneOption: ".d2-none-item",
        noneIconContainer: ".d2-none-item .d2-listfield-icon-container",
        dropDownSearchResultCount: '.d2-searchResultCountDetails',
        lazyloader: '.d2-lazy-loading',
        mobileSearchField: 'input[type="search"]',
        searchClearIcon: '.csui-icon.cancel',
        selectAddNewOption: '.d2mob-combolist-add-new'
      },
      events: {
        'mousedown @ui.addNewOption': 'onClickAddOption',
        'keydown @ui.addNewOption': 'onKeyDownAddOption',
        'mousedown @ui.noneOption': 'onClickNoneOption',
        'keydown @ui.noneOption': 'onKeyDownNoneOption',
        'click .csui-search': 'showInputField',
        'click @ui.searchClearIcon': 'clearSearchText',
        'input @ui.mobileSearchField': 'onSearchInputChange'
      },

      templateHelpers: function () {
        var searchText = utils.sanitizeInputText(this.searchText),
          label = searchText.length > 0 ? _.str.sformat(Lang.addNewItem, searchText) : Lang.addNew;
        return {
          isEditableList: this.options.isEditableList,
          addNewLabel: label,
          addNewId: _.uniqueId('listitem'),
          noneLabel: Lang.selectFieldDefaultLabel,
          showMobileContainer: utils.isMobile(),
          searchPlaceHolder: Lang.mobileInlineSearchPlaceHolder,
          showInfo: this.options.maxSelection > 0,
          infoMsg: _.str.sformat(Lang.maxTasksInfo, this.options.maxSelection)
        };
      },


      constructor: function (/*options*/) {
        this.searchText = '';
        Marionette.CompositeView.prototype.constructor.apply(this, arguments);
        this.resultCount = (this.collection && this.collection.allModels && this.collection.allModels.length > 0) ? this.collection.allModels.length : null;
        this.listenTo(this.collection, 'change:selected', this.updateNoneNode);
        this.updateHeight = this.updateHeight.bind(this);
        // binding to event instead of calling inside onRender as the scrolling behavior has to attach to the new parent
        this.listenTo(this, 'render', this.updateHeight);
        this.listenTo(PubSub, 'hide:overlay:list', this.deactivateOptions);
        this.selectedCollection = this.options.parentView.selectedCollection;
        this.fieldCollection = this.options.fieldCollection;
        this.listenTo(this.selectedCollection, 'update', this.updateSelectedOptions)
      },
      render: function (visible) {
        this._ensureViewIsIntact();
        this._isRendering = true;
        this.resetChildViewContainer();
        this.triggerMethod('before:render', this);
        this._renderTemplate();
        this._renderChildren();
        this._isRendering = false;
        this.isRendered = true;
        this.triggerMethod('render', this, visible);
        return this;
      },

      openSearchView: function (displayView) {
        displayView ? !this.isOpen && this.$el.animate({scrollTop: 0}, 50) : this.isOpen && this.$el.animate({scrollTop: 56}, 50);
        this.isOpen = displayView;
      },

      onRender: function (view, visible) {
        this.ui.lazyloader.hide();
        this.updateNoneNode();
        if (!visible) {
          this.hideOptions();
        }
        if (utils.isMobile()) {
          this.$el.addClass('d2-listfield-mobile-options-container csui-listview');
          this.shouldOpenSearchView();
        }
      },

      shouldOpenSearchView: function () {
        var self = this,
          position = this.ui.options.scrollTop();
        this.ui.options.on('scroll', function () {
          var displayView = self.ui.options.scrollTop() < 10 || self.ui.options.scrollTop() < position || self.ui.mobileSearchField.val();
          self.openSearchView(displayView);
          position = self.ui.options.scrollTop();
        });
      },

      search: function (searchText) {
        if (!this.isVisible()) {
          this.triggerMethod('activate:options');
        }
        if (this.searchText !== searchText) {
          this.ui.dropDownSearchResultCount.removeClass('d2-combo-no-result');
          this.triggerMethod('text:search', searchText);
          this.searchText = searchText;
          this.pullData({'filter': searchText, validateSearchText: true}).done(_.bind(function () {
            if (this.searchText === searchText) {
              this.filterOptions.call(this, searchText);
            }
          }, this));
        }
      },

      filterOptions: function (searchText) {
        if (searchText.length > 0) {
          searchText = searchText.replace(/[.+^${}()|[\]\\]/g, '\\$&');
          searchText = searchText.replace(/\?/g, ".");
          searchText = searchText.replace(/\*/g, ".*?");
        }

        // Incase of hierarchy list, creating a new object to store visited nodes info
        // Storing visited nodes info helps in skipping recomputation of same node
        if (this.options?.showOptionsInHierarchy) {
          this.options.parentView.alreadyVisitedNodes = {};
        }

        this.collection.setOptionsFilter(searchText, 'searchText').always(_.bind(function () {
          if (utils.isMobile()) {
            this._renderChildren();
            this.updateAddNewNode();
          } else {
            this.render(true);
          }
          this.updateSearchResultMessage();
          if (searchText.length > 0) {
            this.ui.noneOption.hide();
          }
          var exactMatches = _.filter(this.collection.allModels, function (model) {
            return (model.get('exactMatch') === true);
          });
          if (exactMatches.length === 1) {
            this.ui.addNewOption.hide();
          } else {
            this.ui.addNewOption.show();
          }

          // Delete visitedNodes info from parentView for hierarchy list after collection is filtered
          if (this.options?.parentView?.alreadyVisitedNodes) {
            delete this.options.parentView.alreadyVisitedNodes;
          }
        }, this));
      },

      showOptions: function (label) {
        if (this.isVisible()) {
          return;
        }

        this.$el.removeClass('binf-hide');
        this.$el.addClass('binf-show');
        var self = this;
        if (utils.isMobile()) {
          PubSub.trigger('list:options:show');
          $(window).on('resize.listField', this.updateHeight);
          csui.require([
            'mobile/utils/platform.controller'
          ], function (PlatformController) {
            PlatformController.clearButtons();
            PlatformController.setHeader({
              title: label,
              backButtonVisible: true
            });
            PlatformController.setBackButton(_.bind(self.deactivateOptions, self));
          });
        }
        this.pullData();
        if (this.options.alpacaField && this.options.alpacaField.isRequired()) {
          this.ui.noneOption.hide();
        }
        this.updateHeight();
      },

      deactivateOptions: function () {
        this.triggerMethod('deactivate:options');
        PubSub.trigger('list:options:hide');
        $(window).off('resize.listField', this.updateHeight);
      },

      hideOptions: function () {
        this.searchText = '';
        if (this.collection.allModels && this.collection.allModels.length > 0) {
          this.collection.setOptionsFilter(this.searchText, 'searchText');
        }
        this.render(true);
        this.$el.removeClass('binf-show');
        this.$el.addClass('binf-hide');
      },
      setFocus: function () {
        var firstItem = this.children.findByIndex(0) && this.children.findByIndex(0).$el.find('a'),
          count = 0;
        while (firstItem && !firstItem.is(':visible')) {
          count++;
          firstItem = this.children.findByIndex(count) && this.children.findByIndex(count).$el.find('a');
        }
        if (firstItem) {
          firstItem.attr('tabindex', 0);
          firstItem.trigger('focus');
        } else if (this.ui.noneOption.length && this.ui.noneOption.css('display') !== 'none') {
          this.ui.noneOption.find('a') && this.ui.noneOption.find('a').trigger('focus');
        } else if (this.ui.dropDownSearchResultCount.length === 1 && !this.ui.dropDownSearchResultCount.hasClass('binf-hidden')) {
          this.ui.dropDownSearchResultCount.trigger('focus');
        } else if (this.ui.addNewOption.length === 1) {
          this.ui.addNewOption.find('a').trigger('focus');
        }
      },
      isVisible: function () {
        return this.$el.is(':visible');
      },
      enableDisableField: function (enabled) {
        if (!enabled) {
          this.hideOptions();
        }
      },
      onClickAddOption: function (event) {
        event.preventDefault();
        event.stopPropagation();
        var searchText = utils.sanitizeInputText(this.searchText);
        if (searchText.length > 0) {
          var newModel = new FieldOptionModel({
            id: searchText,
            name: searchText,
            uniqueOptionId: _.uniqueId(this.options.alpacaField.name + '_option_')
          });
          this.collection.add(newModel);
          this.fieldCollection.add(newModel.attributes);
          newModel.set('selected', true);
          this.updateSearchResultMessage();
          if (this.options.isEditableList == 'false'){
            this.ui.addNewOption.hide();
          }
          this.searchText = '';
        } else {
          if(utils.isMobile()) {
            this.addMobileSpecificPlaceHolder();
          } else{
            this.triggerMethod('activate:typein');
          }
        }
      },
      onKeyDownAddOption: function (event) {

        //if enter or space
        if (event.keyCode === 13 || event.keyCode === 32) {
          this.onClickAddOption(event);
        }
      },
      onClickNoneOption: function (event) {
        event.preventDefault();
        event.stopPropagation();
        var someModelsAreNonEmpty = this.collection.allModels.some(function (model) {
            return !model.isEmpty();
        });
        var me = this,
            selectedModels = _.filter(someModelsAreNonEmpty ? this.collection.allModels : this.collection.models, function (model) {
                return (model.get('selected') === true);
            });
        if (selectedModels && selectedModels.length > 0) {
          _.each(selectedModels, function (selModel) {
            selModel.set('selected', false);
            var matchModel = me.fieldCollection.find(function (fieldModel) {
              return (fieldModel.get('id') === selModel.get('id'))
            });
            if (matchModel) {
              matchModel.set('selected', false);
            }
          });
        }
        this.ui.noneIconContainer.addClass('d2-icon-checkmark');
        this.ui.noneOption.addClass('d2-field-selected');
      },

      onKeyDownNoneOption: function (event) {
        //if enter or space
        if (event.keyCode === 13 || event.keyCode === 32) {
          this.onClickNoneOption(event);
        }
      },

      updateSelectedOptions: function (collection, options) {
        var me = this;
        if (options && options.changes && options.changes.removed && options.changes.removed.length > 0) {
          _.each(options.changes.removed, function (removed) {
            var modelsToCheck = me.options.isEditableList ? _.union(me.collection.models, me.collection.allModels) : me.collection.allModels;
            var removedOption = _.find(modelsToCheck, function (model) {
              return removed.get('id') === model.get('id');
            });
            if (removedOption) {
              removedOption.set('selected', false);
            }
          })
        }
      },

      updateNoneNode: function (/*hideNoneNode*/) {
        // Check if allModels have 0 attributes
          var allModelsIsEmpty = this.collection.allModels.every(function (model) {
            return Object.keys(model.attributes).length === 0;
          });

          var selectedModels = _.filter(allModelsIsEmpty ? this.collection.models : this.collection.allModels, function (model) {
            return (model.get('selected') === true);
          });
        if (selectedModels.length === 0) {
          this.ui.noneIconContainer.addClass('d2-icon-checkmark');
          this.ui.noneOption.addClass('d2-field-selected');
        } else {
          this.ui.noneIconContainer.removeClass('d2-icon-checkmark');
          this.ui.noneOption.removeClass('d2-field-selected');
        }
      },

      updateHeight: function () {
        var height;
        if (utils.isMobile()) {
          height = $('.cs-perspective-panel').height();
          if (this.ui.mobileSearchField && this.ui.mobileSearchField.val()) {
            height -= this.$('.d2mobile-header')[0].scrollHeight;
          }
          this.ui.options.css('max-height', height);
        } else {
          height = this.options.rows * this.ui.noneOption.outerHeight();
          if (height > 0) {
            this.ui.options.css('height', height);
            this.triggerMethod('ensure:scrollbar');
            this.triggerMethod('update:scrollbar');
          }
        }
      },

      pullData: function (options) {
        options = _.extend({"view": this.options.parentView, 'filter': ''}, options);
        var dfd = $.Deferred(), doUpdateCollection;
        this.ui.dropDownSearchResultCount.addClass('binf-hidden');
        if (ComboDataSourceUtils.isAsynchronousDataSourceField(this.options.alpacaField)
          && (this.options.async === true || this.options.alpacaField.options.ds.dependencies.length !== 0) &&
          (!_.isUndefined(this.options.alpacaField.options.ds.url) || this.options.alpacaField.options.ds['assistance_type'] === 'custom')) {
          this.ui.lazyloader.show();
          this.ui.options.hide();
          this.ui.addNewOption.hide();

          this.options.alpacaField.pullData(options).done(_.bind(function (response) {
            if (utils.isMobile()) {
              this.$el.find('.d2mobile-header').removeClass('binf-hidden');
            }

            doUpdateCollection = _.isEmpty(options.filter) || !options.validateSearchText ||
              (options.validateSearchText && options.filter === this.searchText);

            if (doUpdateCollection) {
              var collectionData = _.map(response, function(model){
                if(model.get('name') !== ''){
                  return model.attributes;
                }
              });
              this.collection.hasMoreRecords = this.fieldCollection.hasMoreRecords;
              this.collection.populate(collectionData, {reset: true}).done(_.bind(function () {
                this.fieldCollection.reset(response);
                this.options.selected.each(function (selectedModel) {
                  var selId = selectedModel.get('id');
                  var mdl = _.find(this.collection.allModels, function (model) {
                    return model.get('id') === selId;
                  });
                  if (mdl) {
                    mdl.set('selected', true);
                  } else {
                    this.fieldCollection.add(selectedModel.attributes);
                    this.collection.add(selectedModel.attributes);
                  }
                }, this);
                if (_.isEmpty(this.searchText)) {
                  this.resultCount = this.collection.allModels.length;
                }
                this.ui.lazyloader.hide();
                this.ui.options.show();
                this.ui.addNewOption.show();
                this.updateSearchResultMessage();
                this.updateHeight();
                dfd.resolve(response);
              }, this));
            } else {
              dfd.resolve();
            }
          }, this)).fail(_.bind(function (err) {
            this.ui.lazyloader.hide();
            dfd.reject(err);
          }, this));

        } else {
          if (utils.isMobile()) {
            this.$el.find('.d2mobile-header').removeClass('binf-hidden');
          }
          dfd.resolve();
        }
        return dfd.promise();
      },
      updateSearchResultMessage: function () {
        if (this.children.length === 0) {
          this.ui.dropDownSearchResultCount.addClass('d2-combo-no-result');
          this.ui.dropDownSearchResultCount.text(Lang.noResultFound);
          this.ui.dropDownSearchResultCount.attr('aria-label', Lang.noResultFound);
          this.ui.dropDownSearchResultCount.removeClass('binf-hidden');
          return;
        } else {
          this.ui.dropDownSearchResultCount.removeClass('d2-combo-no-result');
          this.ui.dropDownSearchResultCount.addClass('binf-hidden');
        }
        if (this.showSearchCount || this.options.async) {
          var message, messageLabel;
          if (this.resultCount === null || this.resultCount === undefined) {
            messageLabel = Lang.showingResultsNoTotal;
          } else if (this.collection.hasMoreRecords) {
            messageLabel = Lang.showingHasMore;
          } else {
            messageLabel = Lang.showingResultsOfMatches
          }
          var matchCount = this.collection.filteredResultCount || this.collection.allModels.length;
          if (_.isEmpty(this.searchText)) {
            message = _.str.sformat(messageLabel, this.resultCount, this.resultCount);
            matchCount = this.collection.hasMoreRecords ? matchCount : 0;
          } else {
            message = _.str.sformat(messageLabel, matchCount, this.resultCount);
          }
          if (matchCount > 0) {
            this.ui.dropDownSearchResultCount.text(message);
            this.ui.dropDownSearchResultCount.attr('aria-label', message);
            this.ui.dropDownSearchResultCount.removeClass('binf-hidden');
          }
        }
      },

      //Start of D2-mobile specific functions for search bar.
      showInputField: function () {
        this.$('.csui-input-before-focus').addClass('binf-hidden');
        this.$('.csui-search .csui-input').removeClass('binf-hidden').trigger('focus');
        this.$('.csui-search').removeClass('csui-search-prompt csui-compact-search');
        if (this.ui.mobileSearchField.val()) {
          this.ui.searchClearIcon.addClass('csui-show');
        }
      },

      clearSearchText: function () {
        this.ui.mobileSearchField.val('');
        this.ui.mobileSearchField.trigger('focus');
        this.ui.searchClearIcon.removeClass('csui-show');
        this.onSearchInputChange();
      },

      onSearchInputChange: function () {
        if (this.ui.mobileSearchField.val()) {
          this.ui.searchClearIcon.addClass('csui-show');
        } else {
          this.ui.searchClearIcon.removeClass('csui-show');
        }
        if (!this.ui.mobileSearchField.val()) {
          this.ui.noneOption.show();
        }
        this.triggerMethod('update:search:filter', this.ui.mobileSearchField.val());
        this.updateHeight();
      },

      addMobileSpecificPlaceHolder: function() {
        this.showInputField();
        this.ui.mobileSearchField.attr("placeholder", Lang.typeNew);
      },

      updateAddNewNode: function() {
        if (this.options.isEditableList) {
          let searchText = utils.sanitizeInputText(this.searchText),
              addNewLabel = searchText.length > 0 ? _.str.sformat(Lang.addNewItem, searchText) : Lang.addNew;
          this.ui.selectAddNewOption.text(addNewLabel);
        }
      }
      //End of D2-mobile specific functions for search bar.
    });
  });