csui.define('d2/utils/landingpage/tiles',[
  'nuc/lib/underscore',
  'd2/utils/landingpage/tile.collection',
  'csui-ext!d2/utils/landingpage/tiles'
], function (_, TileCollection, extTiles) {
  'use strict';

  var tileCollection = new TileCollection();

  var tileDefinitions = [];

  if (extTiles) {
    tileDefinitions = tileDefinitions.concat(_.flatten(extTiles, true));
  }

  tileCollection.add(tileDefinitions, {merge: true});
  
  return tileCollection;
});
