csui.define('d2/server.adaptors/models/node.facets.mixin',[
  'nuc/lib/underscore', 'nuc/lib/jquery'
], function (_, $) {
  'use strict';

  var ServerAdaptorMixin = {
    mixin: function (prototype) {
      return _.extend(prototype, {
        makeServerAdaptor: function (/*options*/) {
          return this;
        },

        // TODO: Either implement faceted browsing, or make facets in
        // Smart UI optional, so that this call will not be made.
        sync: function (method, model, options) {
          var deferred = $.Deferred();
          options = _.defaults({parse: false}, options);
          this.trigger('request', this, {}, options);
          setTimeout(function () {
            options.success.call(options.context, {}, 'success', {});
            deferred.resolve();
          }.bind(this));
          return deferred.promise();
        },
        //Added the needed function in node facet mixin for unblocking the UI.Need to validate functional Impact. #JIRA DTWO-116344
        getFilterQuery: getFilterQuery,
        getFilterQueryValue: getFilterQueryValue
      });
    },

    getFilterQuery: getFilterQuery,
    getFilterQueryValue: getFilterQueryValue
  };

  function getFilterQuery(filters) {
    var value = getFilterQueryValue(filters);
    return value.length && $.param({
          where_facet: value
        }, true) || '';
  }

  function getFilterQueryValue(filters) {
    return filters && _.map(filters, getFilterValue) || [];
  }

  function getFilterValue(filter) {
    return filter.id + ":" +
           _.reduce(filter.values, function (result, value) {
             if (result) {
               result += "|";
             }
             return result + value.id.toString();
           }, "");
  }

  return ServerAdaptorMixin;
});
