csui.define('d2/overrides/csui/controls/breadcrumbs/breadcrumbs.view',[
  'nuc/lib/underscore',
  'csui/controls/breadcrumbs/breadcrumbs.view',
  'csui/utils/contexts/factories/next.node',
  'd2/utils/contexts/factories/node.navigation'
], function (_, BreadcrumbsView, NextNodeModelFactory, NodeNavigationFactory) {
  'use strict';

  BreadcrumbsView.prototype.onClickAncestor = function (model, node) {
    var context = this.context = this.options.context;
    this._nextNode = this.options.node || context.getModel(NextNodeModelFactory);

    // TODO - see if we can remove this duplication of CSUI code. Only thing changed is to check id is not '*' and
    // setting '_is_home_cabinet' in addition to 'id'
    if (node.get('id') !== '*') {
      var args = {node: node},
        nodeNavigationCollection = context && context.getCollection(NodeNavigationFactory);
      this.trigger('before:defaultAction', args);
      if (!args.cancel) {
        var nodeId = node.get('id');
        if (this._nextNode.get('id') === nodeId) {
          // when id is same as nextNode's id, nextNode.set(id) event is not triggered
          this._nextNode.unset('id', {silent: true});
        }

        var viewStateModel = this.context && this.context.viewStateModel;
        var viewState = viewStateModel && viewStateModel.get('state');
        if (viewState) {
          this.context.viewStateModel.set('state', _.omit(viewState, 'filter'), {silent: true});
        }

        // The nodestable uses this event to remove the order_by from the viewStateModel
        this._nextNode.trigger('before:change:id', node, this);
        viewStateModel && viewStateModel.set('browsing', true);
        this._nextNode.set({
          id: nodeId
        });
        // Set home cabinet flag separately because framework code blanks out all attributes of nextNode on setting id
        this._nextNode.set({
          _is_home_cabinet: node.get('_is_home_cabinet')
        });

        if(nodeNavigationCollection){
          // bread crumb selection should reset the node navigation collection
          var navigationArray = [];
          this.collection.some(function (node) {
            navigationArray.push({'id': node.get('id'), 'name': node.get('name')});
            if (node.get('id') === nodeId) {
              return true;
            }
          }, this);
          nodeNavigationCollection.reset(navigationArray);
        }
      }
    }
  };

});
