/*
 * This is based on the code in bridge.js file in D2 X3 Portal codebase.
 * Changes done are:
 *   1. Use jquery to simplify iframe creation
 *   2. Simplify GC logic to just simple setTimeout for each iframe created (copied from smartui)
 */
csui.define('d2/utils/download.manager',[
  'module',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/utils/base',
  'nuc/utils/log',
  'nuc/utils/connector',
  'dctmw/utils/utils'
], function (module, _, $, base, log, Connector, utils) {
  'use strict';

  log = log(module.id);

  function fixUrlContentDisposition(url) {
    var cdStr = '&content_disposition=inline';
    if (url.indexOf(cdStr) >= 0) {
      url = url.replace(cdStr, '');
    }
    return url;
  }

  var DownloadManager = {
    // Default iFrame container
    iFrameContainer: document.body,
    // counter used to generate a unique element id for each new iframe
    nextIFrameId: 1,

    // Download a file using an HTTP GET request.
    //
    // If downloadUrls is a string, it is interpreted as a single url.
    // If downloadUrls is an array, it is interpreted as an array of urls.
    // If there is more than one url, the next url is tried if the previous
    // one failed until there are no more urls. If the file could not be
    // downloaded and errCallback is defined, then it is called with the event
    // of the last download failure and a string list of hostnames
    // corresponding to the given download urls.
    downloadFile: function (downloadUrls, errCallback, win) {
      if (!downloadUrls) {
        return false;
      }

      var url = downloadUrls;
      if (typeof(downloadUrls) !== 'string') {
        url = downloadUrls[0];
      }

      if (!url || url.length === 0) {
        return false;
      }

      if (win) {
        utils.openUrlInWindow(url, win, true);
        return true;
      }

      var iframe = this._newIFrame();
      var remainingUrls = (typeof(downloadUrls) === 'string') ? [downloadUrls] : downloadUrls;
      var hostsTried = [];

      var onloadContext = {
        iframe: iframe,
        remainingUrls: remainingUrls,
        hostsTried: hostsTried,
        errCallback: errCallback
      };

      var me = this;
      iframe.onload = function (event) {
        _.bind(me._onloadIFrame, me, event, onloadContext)();
      };

      hostsTried.push(this._getHostName(url));
      log.debug('Attempting to download file using url: ' + url);

      iframe.src = fixUrlContentDisposition(url);

      return true;
    },

    _newIFrame: function () {
      var id = 'download_iframe_' + this.nextIFrameId++,
        iframe = $('<iframe></iframe>')
          .hide()
          .attr('id', id)
          .attr('name', id)
          .attr('title', 'Download')
          .appendTo($(this.iFrameContainer));

      var delay = Math.min(Connector.prototype.connectionTimeout || 60 * 1000, 60 * 1000);
      setTimeout(function () {
        iframe.remove();
      }, delay);

      return iframe[0];
    },

    _onloadIFrame: function (event, context) {
      // If we are here, that means download using the previous url failed
      log.warn('Download attempt with previous url failed');

      if (context.remainingUrls.length > 1) {
        // Try the next url
        context.remainingUrls = context.remainingUrls.slice(1);
        var url = context.remainingUrls[0];
        context.hostsTried.push(this._getHostName(url));
        log.debug('Attempting to download file using url: ' + url);

        context.iframe.src = fixUrlContentDisposition(url);
      } else {
        if (context.errCallback) {
          context.errCallback(event, context.iframe.contentDocument, context.hostsTried.join('\n'));
        }
        // No more urls to try: dispose iframe and notify application
        this._disposeIFrame(context.iframe);
      }
    },

    _disposeIFrame: function (iframe) {
      try {
        this.iFrameContainer.removeChild(iframe);
      } catch (ex) {
        log.warn('_disposeIFrame: ' + iframe.id + ' no longer in DOM');
      }
    },

    _getHostName: function (url) {
      return $('<a>').prop('href', url).prop('host');
    }
  };

  return DownloadManager;
});
