csui.define('d2/server.adaptors/models/node.addable.type.mixin',[
  'nuc/lib/underscore', 'nuc/lib/jquery'
], function (_, $) {
  'use strict';

  var ServerAdaptorMixin = {
    mixin: function (prototype) {
      return _.extend(prototype, {
        makeServerAdaptor: function (/*options*/) {
          return this;
        },

        sync: function (method, model, options) {
          var deferred = $.Deferred();
          options = _.defaults({parse: false}, options);
          this.trigger('request', this, {}, options);
          setTimeout(function () {
            options.success.call(options.context, {}, 'success', {});
            deferred.resolve();
          }.bind(this));
          return deferred.promise();
        }

      });
    }
  };

  return ServerAdaptorMixin;
});
